// @effect-diagnostics nodeBuiltinImport:off -- run ids are generated by the server.
import * as NodeCrypto from "node:crypto";

import {
  ComputeResultsError,
  ComputeSessionId,
  type ComputeResultsRerunResult,
  type NotebookFreshRun,
} from "@t3tools/contracts";
import * as Cause from "effect/Cause";
import * as Context from "effect/Context";
import * as Deferred from "effect/Deferred";
import * as Effect from "effect/Effect";
import * as Layer from "effect/Layer";
import * as Schema from "effect/Schema";
import * as Scope from "effect/Scope";

const RETAINED_RUNS = 128;
const isResultsError = Schema.is(ComputeResultsError);

export type NotebookJobDetails = Omit<NotebookFreshRun, "runId" | "outcome">;
export type ReportNotebookJob = (update: NotebookJobDetails) => boolean;

const stopped = { _tag: "failed", message: "The notebook run was stopped." } as const;

interface Job {
  readonly key: string;
  readonly runId: ComputeSessionId;
  readonly done: Deferred.Deferred<ComputeResultsRerunResult>;
  readonly cancel: Deferred.Deferred<void>;
  details: NotebookJobDetails;
  outcome?: ComputeResultsRerunResult;
}

export const makeNotebookRunJobs = Effect.gen(function* () {
  const scope = yield* Scope.Scope;
  const jobs = new Map<ComputeSessionId, Job>();

  const find = (key: string, runId?: ComputeSessionId) => {
    const job =
      runId === undefined
        ? [...jobs.values()].findLast((entry) => entry.key === key)
        : jobs.get(runId);
    return job?.key === key ? job : undefined;
  };

  const status = (job: Job): NotebookFreshRun => ({
    runId: job.runId,
    ...(job.outcome === undefined ? {} : { outcome: job.outcome }),
    ...job.details,
  });

  return {
    start: Effect.fn("NotebookRunJobs.start")(function* (
      key: string,
      execute: (
        report: ReportNotebookJob,
      ) => Effect.Effect<ComputeResultsRerunResult, ComputeResultsError>,
      details: NotebookJobDetails = {},
    ) {
      const previous = find(key);
      if (previous !== undefined && previous.outcome === undefined)
        return yield* new ComputeResultsError({
          message: "This notebook already has a fresh run.",
        });
      const runId = ComputeSessionId.make(NodeCrypto.randomUUID());
      const job: Job = {
        key,
        runId,
        details,
        done: Deferred.makeUnsafe(),
        cancel: Deferred.makeUnsafe(),
      };
      jobs.set(runId, job);
      const work = execute((update) => {
        if (job.details.progress?.phase === "stopping") return false;
        job.details = { ...job.details, ...update };
        return true;
      });
      yield* Effect.raceFirst(work, Deferred.await(job.cancel).pipe(Effect.as(stopped))).pipe(
        Effect.catchCause((cause) => {
          const error = Cause.squash(cause);
          return Effect.logWarning("Fresh notebook run failed", {
            runId,
            cause: Cause.pretty(cause),
          }).pipe(
            Effect.as<ComputeResultsRerunResult>({
              _tag: "failed",
              message: isResultsError(error) ? error.message : "The notebook could not run.",
            }),
          );
        }),
        Effect.flatMap((outcome) =>
          Effect.gen(function* () {
            job.outcome = outcome;
            yield* Deferred.succeed(job.done, outcome);
            for (const entry of jobs.values()) {
              if (jobs.size <= RETAINED_RUNS) break;
              if (entry.outcome !== undefined) jobs.delete(entry.runId);
            }
          }),
        ),
        Effect.interruptible,
        Effect.forkIn(scope, { uninterruptible: false }),
      );
      return status(job);
    }, Effect.uninterruptible),
    stop: Effect.fn("NotebookRunJobs.stop")(function* (key: string, runId: ComputeSessionId) {
      const job = find(key, runId);
      if (job === undefined) return null;
      if (job.outcome === undefined && job.details.progress?.phase !== "saving") {
        job.details = {
          ...job.details,
          progress: { cell: 0, total: 0, ...job.details.progress, phase: "stopping" },
        };
        yield* Deferred.succeed(job.cancel, undefined);
      }
      return status(job);
    }),
    status: (key: string, runId?: ComputeSessionId) =>
      Effect.sync(() => {
        const job = find(key, runId);
        return job === undefined ? null : status(job);
      }),
    wait: (key: string, runId: ComputeSessionId) =>
      Effect.suspend(() => {
        const job = find(key, runId);
        return job === undefined
          ? Effect.succeed({
              _tag: "failed" as const,
              message: "This notebook run is unavailable.",
            })
          : Deferred.await(job.done);
      }),
  };
});

export class NotebookRunJobs extends Context.Service<
  NotebookRunJobs,
  Effect.Success<typeof makeNotebookRunJobs>
>()("t3/scient/notebook/NotebookRunJobs") {}

export const layer = Layer.effect(NotebookRunJobs, makeNotebookRunJobs);
